function hmdfg_place_similarity(string $a,string $b): float {
    $a=hmlg_place_key($a);$b=hmlg_place_key($b);if($a===''||$b==='')return 0.0;if($a===$b)return 1.0;
    $aa=array_values(array_unique(fc_tokens($a,true)));$bb=array_values(array_unique(fc_tokens($b,true)));$x=array_fill_keys($aa,true);$y=array_fill_keys($bb,true);$u=count($x+$y);$j=$u?count(array_intersect_key($x,$y))/$u:0.0;$m=max(strlen($a),strlen($b));$l=$m?1-levenshtein($a,$b)/$m:0.0;return max($j,$l*0.93);
}
