        $sourcePlaces=array_values(array_unique(array_filter([(string)($src['town']??''),(string)($geo['town']??''),(string)($geo['parent']??''),(string)($obs['region_name']??'')],static fn($v)=>trim($v)!=='')));$placeRank=[];foreach($sourcePlaces as $sp)foreach($catalogPlaces[$country]??[] as $pk=>$meta){$score=hmdfg_place_similarity($sp,$pk);if($score>=0.72)$placeRank[]=['source'=>$sp,'target_key'=>$pk,'score'=>round($score,6),'ids'=>array_map('intval',array_keys($meta['ids']))];}usort($placeRank,static fn($a,$b)=>$b['score']<=>$a['score']);$bestPlace=$placeRank[0]??null;if(!$bestPlace){$stats['no_place_match']++;$reasons['no_direct_fuzzy_place_match']=($reasons['no_direct_fuzzy_place_match']??0)+1;continue;}$secondPlace=$placeRank[1]['score']??0.0;if($bestPlace['score']<0.84||($secondPlace>0&&$bestPlace['target_key']!==($placeRank[1]['target_key']??'')&&$bestPlace['score']-$secondPlace<0.10)){$stats['place_ambiguous']++;$reasons['weak_or_ambiguous_place_match']=($reasons['weak_or_ambiguous_place_match']??0)+1;continue;}$stats['place_match']++;
